// Generated by app-portfolio/scripts/build_arcade.py. Do not edit: change the template there.
import { expect, test, type Page } from '@playwright/test';
import rawCatalog from '../src/arcade/catalog.json';

const APP = 'worthit';
type Game = { id: string; mechanic: string; tier: string };
const catalog = rawCatalog as unknown as { games: Game[] };

async function openArcade(page: Page) {
  await page.addInitScript((app) => {
    if (!localStorage.getItem(`${app}.prefs`)) localStorage.setItem(`${app}.prefs`, JSON.stringify({ state: { onboarded: true }, version: 1 }));
  }, APP);
  await page.route('https://kaoticchainz.com/arcade/**', (route) => route.fulfill({ path: `e2e/fixtures/arcade/${new URL(route.request().url()).pathname.replace(/^\/arcade\//, '')}`, contentType: 'application/json' }));
  await page.goto('/arcade');
  const unlock = page.getByTestId('unlock');
  await expect(page.getByTestId('arcade').or(unlock)).toBeVisible();
  if (await unlock.isVisible()) await unlock.click();
  await expect(page.getByTestId('arcade')).toBeVisible();
}

test('gems: a welcome gift, and gems swap into the app currency', async ({ page }) => {
  await openArcade(page);
  await expect(page.getByTestId('arcade-gems')).toHaveText('10 💎');
  await page.getByTestId('swap-1').click();
  await expect(page.getByTestId('arcade-gems')).toHaveText('9 💎');
  await expect(page.getByTestId('arcade-balance')).toHaveText(/^10 /);
});

test('a mistake offers one revive, paid in gems, and the round carries on', async ({ page }) => {
  const g = catalog.games.find((x) => x.tier === 'free' && (x.mechanic === 'stack' || x.mechanic === 'sequence'));
  test.skip(!g, 'no free game that ends on a mistake');
  await openArcade(page);
  // Tap it like a person would. A page reload would re-lock apps with a lock screen.
  await page.getByTestId(`game-${g!.id}`).click();
  await page.getByTestId('game-start').click();
  await expect(page.getByTestId('game-score')).toBeVisible({ timeout: 8000 });
  const revive = page.getByTestId('revive');
  for (let i = 0; i < 60 && !(await revive.isVisible()); i++) {
    if (g!.mechanic === 'stack') await page.getByTestId('stack-drop').click();
    else if (await page.getByText(/Your turn/).isVisible()) await page.getByTestId('seq-0').click();
    await page.waitForTimeout(g!.mechanic === 'stack' ? 60 : 250);
  }
  await expect(revive).toBeVisible();
  await page.getByTestId('revive-gems').click();
  await expect(revive).toBeHidden();
  await expect(page.getByTestId('game-score')).toBeVisible();
  await page.getByTestId('game-end').click();
  await expect(page.getByTestId('game-final')).toBeVisible();
});
